(()=>{const e=["ayu","navy","coal"],t=["light","rust"],o=document.getElementsByTagName("html")[0].classList;let n=!0;for(const t of o)if(e.includes(t)){n=!1;break}const d=n?"default":"dark";mermaid.initialize({startOnLoad:!0,theme:d});for(const t of e)document.getElementById("mdbook-theme-"+t).addEventListener("click",()=>{n&&window.location.reload()});for(const e of t)document.getElementById("mdbook-theme-"+e).addEventListener("click",()=>{n||window.location.reload()})})();